async function save(){clearTimeout(saveTimer);if(membershipSaveBarrier){const result=await membershipSaveBarrier.promise;if(result?.error)throw result.error;if(dirty)return save();return;}if(savePromise){await savePromise;if(dirty)return save();return;}if(!dirty)return;saving=true;dirty=false;updateSaveStatus();const payload=JSON.stringify(project);savePromise=api('/api/projects/'+project.id,{method:'PUT',body:payload}).then(p=>{project.revision=p.revision;project.updatedAt=p.updatedAt;}).catch(e=>{dirty=true;throw e;}).finally(()=>{saving=false;savePromise=null;updateSaveStatus();});await savePromise;if(dirty)return save();}
