function promptReferenceMarkup(node){const ids=node.params?.promptAssetIds||[],assets=ids.map(id=>libraryAssets.find(a=>a.id===id)||project.assets.find(a=>a.id===id)).filter(Boolean);return `<div class="prompt-reference-chips" aria-label="已引用素材">${assets.map(a=>`<span class="prompt-reference-chip"><img src="/media/${encodeURIComponent(a.id)}" alt=""><span title="${esc(a.name)}">${esc(a.name)}</span><button type="button" data-remove-prompt-asset="${esc(a.id)}" aria-label="移除${esc(a.name)}">×</button></span>`).join('')||'<span class="small muted">未引用图片</span>'}</div>`;}
function installPromptMentionEditor(){const input=document.querySelector('.panel [data-field="text"]');if(!input||input.readOnly||!project)return;const parent=input.closest('label');if(!parent||parent.nextElementSibling?.id==='prompt-mention-wrap')return;const node=project.nodes.find(n=>n.id===selected);if(!node||node.type==='loop')return;const wrap=document.createElement('div');wrap.id='prompt-mention-wrap';wrap.className='prompt-mention-wrap';wrap.innerHTML=`${promptReferenceMarkup(node)}<div id="prompt-mention-menu" class="prompt-mention-menu" role="listbox" aria-label="选择图片素材" hidden></div><p class="small muted">在提示词中输入 @，从全局素材库选择图片作为本节点参考。</p>`;parent.after(wrap);}
function mentionTrigger(input){const cursor=input.selectionStart??input.value.length,left=input.value.slice(0,cursor),at=left.lastIndexOf('@');if(at<0||left.slice(at+1).includes('\n')||/\s/u.test(left.slice(at+1))||at>0&&/[\w@]/u.test(left[at-1]))return null;return{start:at,end:cursor,query:left.slice(at+1)};}
function mentionAssets(query,node){const merged=new Map([...project.assets,...libraryAssets].map(a=>[a.id,a])),selectedIds=new Set(node.params?.promptAssetIds||[]),needle=query.trim().toLocaleLowerCase();return[...merged.values()].filter(a=>promptImageTypes.has(a.type)&&Number.isFinite(a.size)&&a.size>0&&a.size<=10*1024*1024&&!selectedIds.has(a.id)&&(!needle||[a.name,...(a.tags||[])].join(' ').toLocaleLowerCase().includes(needle))).slice(0,8);}
function renderPromptMentionMenu(input,trigger){const menu=$('#prompt-mention-menu'),node=project?.nodes.find(n=>n.id===selected);if(!menu||!input.isConnected||!node)return;menu.dataset.start=String(trigger.start);menu.dataset.end=String(trigger.end);mentionActiveIndex=0;const assets=mentionAssets(trigger.query,node);menu.innerHTML=assets.length?assets.map((a,i)=>`<button type="button" role="option" aria-selected="${i===0}" data-prompt-asset="${esc(a.id)}" data-mention-start="${trigger.start}" data-mention-end="${trigger.end}"><img src="/media/${encodeURIComponent(a.id)}" alt=""><span><b>${esc(a.name)}</b><small>${esc(a.category||'全局素材库')} · PNG/JPEG/WebP</small></span></button>`).join(''):'<p class="small muted">没有匹配的可用图片（仅支持不超过10MB的PNG、JPEG、WebP）</p>';menu.hidden=false;}
async function updatePromptMentionMenu(input){const menu=$('#prompt-mention-menu'),trigger=mentionTrigger(input),node=project?.nodes.find(n=>n.id===selected);if(!menu||!node)return;if(!trigger){menu.hidden=true;return;}menu.innerHTML='<p class="small muted">正在读取素材库…</p>';menu.hidden=false;renderPromptMentionMenu(input,trigger);if(Date.now()-libraryLoadedAt>20000){try{await refreshLibrary();}catch(error){toast('读取全局素材库失败：'+error.message);return;}if(input.isConnected){const latest=mentionTrigger(input);if(latest&&latest.start===trigger.start&&latest.query===trigger.query)renderPromptMentionMenu(input,latest);}}}
