function selectPromptAsset(button){const node=project?.nodes.find(n=>n.id===selected),input=document.querySelector('.panel [data-field="text"]'),menu=$('#prompt-mention-menu');if(!node||!input||!menu)return;const id=button.dataset.promptAsset,asset=libraryAssets.find(a=>a.id===id)||project.assets.find(a=>a.id===id);if(!asset||!promptImageTypes.has(asset.type)||!Number.isFinite(asset.size)||asset.size<=0||asset.size>10*1024*1024)throw new Error('仅支持不超过10MB的PNG、JPEG或WebP图片');node.params??={};const ids=node.params.promptAssetIds||[];if(!ids.includes(id)&&ids.length>=20)throw new Error('每个节点最多引用20张图片');if(promptTextEditNodeId!==node.id){checkpoint();promptTextEditNodeId=node.id;}if(!project.assets.some(a=>a.id===id))project.assets.push(structuredClone(asset));if(!ids.includes(id))node.params.promptAssetIds=[...ids,id];const start=Number(button.dataset.mentionStart),end=Number(button.dataset.mentionEnd),from=Number.isInteger(start)?start:input.selectionStart,to=Number.isInteger(end)?end:input.selectionEnd,name=String(asset.name).replace(/[\r\n]+/g,' ').trim(),token='@'+name;input.value=input.value.slice(0,from)+token+input.value.slice(to);input.focus();input.setSelectionRange(from+token.length,from+token.length);node.text=input.value;changed(false);syncEditedCanvasNode(node);syncPromptReferenceChips(node);menu.hidden=true;}
