function applyPreviewViewport(){const world=$('#world');if(world)world.style.transform=`translate(${project.viewport.x}px,${project.viewport.y}px) scale(${project.viewport.zoom})`;const label=$('#zoom-label');if(label)label.textContent=`${Math.round(project.viewport.zoom*100)}%`;drawEdges();}
function exitZoomPreview(restore=true,notify=false){if(!zoomPreviewState)return;const previous=zoomPreviewState;zoomPreviewState=null;document.body.classList.remove('canvas-zoom-preview');if(restore)project.viewport={...previous};applyPreviewViewport();if(notify)toast('已恢复原画布视图');}
function toggleZoomPreview(){if(zoomPreviewState){exitZoomPreview(true,true);return;}if(!project?.nodes?.length||view!=='canvas')return;zoomPreviewState={...project.viewport};const canvas=$('#canvas'),rect=canvas.getBoundingClientRect(),bounds=project.nodes.map(node=>{const el=document.querySelector(`[data-node="${CSS.escape(node.id)}"]`);return{x:node.x,y:node.y,w:el?.offsetWidth||288,h:el?.offsetHeight||220};});const minX=Math.min(...bounds.map(r=>r.x)),minY=Math.min(...bounds.map(r=>r.y)),maxX=Math.max(...bounds.map(r=>r.x+r.w)),maxY=Math.max(...bounds.map(r=>r.y+r.h)),pad=90,width=maxX-minX+pad*2,height=maxY-minY+pad*2,zoom=Math.max(.06,Math.min(1,(rect.width-80)/width,(rect.height-100)/height));project.viewport={zoom,x:rect.width/2-(minX+maxX)/2*zoom,y:rect.height/2-(minY+maxY)/2*zoom};document.body.classList.add('canvas-zoom-preview');applyPreviewViewport();toast('总览预览：再按 Z 返回原视图');}
function zoom(delta,clientX,clientY){const v=project.viewport,box=$('#canvas').getBoundingClientRect(),z=Math.min(3,Math.max(.15,v.zoom*delta)),cx=Number.isFinite(clientX)?clientX-box.left:box.width/2,cy=Number.isFinite(clientY)?clientY-box.top:box.height/2;v.x=cx-(cx-v.x)*z/v.zoom;v.y=cy-(cy-v.y)*z/v.zoom;v.zoom=z;changed();}
function fit(){if(!project.nodes.length)return;const rect=$('.surface').getBoundingClientRect();const minX=Math.min(...project.nodes.map(n=>n.x)),minY=Math.min(...project.nodes.map(n=>n.y)),maxX=Math.max(...project.nodes.map(n=>n.x))+320,maxY=Math.max(...project.nodes.map(n=>n.y))+300;const z=Math.min(1.2,Math.max(.15,Math.min((rect.width-100)/(maxX-minX),(rect.height-200)/(maxY-minY))));project.viewport={zoom:z,x:(rect.width-(maxX-minX)*z)/2-minX*z,y:100-minY*z};changed();}
function layout(){checkpoint();project.nodes.forEach((n,i)=>{n.x=100+(i%3)*360;n.y=120+Math.floor(i/3)*330;});fit();}
