  if(b.dataset.filter){assetFilter=b.dataset.filter;assetPage=1;await loadAssetPage();return true;}
  if(b.dataset.assetPage){const page=Number(b.dataset.assetPage);if(!Number.isSafeInteger(page))throw new Error('素材页码无效');assetPage=Math.max(1,page);await loadAssetPage();return true;}
  if(b.dataset.classificationRecords){await showAssetClassificationRecords(b.dataset.classificationRecords,b.dataset.classificationTask||'');return true;}
  if(b.dataset.captionAsset){await openAssetCaptions({projectId:project.id,assetIds:[b.dataset.captionAsset],onChange:async()=>{await refreshLibrary({refreshPage:true});draw();}});return true;}
  if(b.dataset.classifyAsset){await openAssetClassification(b.dataset.classifyAsset);return true;}
  if(b.dataset.action==='submit-asset-classification'){await submitAssetClassification(b);return true;}
  if(b.hasAttribute('data-asset-reload')){await loadAssetPage();return true;}
  if(b.dataset.useAsset){const a=libraryAssets.find(a=>a.id===b.dataset.useAsset)||assetRows.find(a=>a.id===b.dataset.useAsset)||project.assets.find(a=>a.id===b.dataset.useAsset);if(a&&!project.assets.some(x=>x.id===a.id)){checkpoint();project.assets.push(structuredClone(a));}useAsset(a);if($('#modal').open)$('#modal').close();return true;}
  if(b.dataset.editShot){shotDialog(b.dataset.editShot);return true;}
  if(b.dataset.previewShot){stopPlayback();selectedShot=b.dataset.previewShot;draw();return true;}
  if(b.dataset.moveShot){checkpoint();const i=project.shots.findIndex(s=>s.id===b.dataset.moveShot),j=i+Number(b.dataset.direction);if(j>=0&&j<project.shots.length)[project.shots[i],project.shots[j]]=[project.shots[j],project.shots[i]];changed();return true;}
  if(b.dataset.skill||b.dataset.template){await save();project=await api(`/api/projects/${project.id}/apply-skill`,{method:'POST',body:JSON.stringify({skillId:b.dataset.skill,templateId:b.dataset.template})});undo=[];redo=[];$('#modal').close();view='canvas';fit();toast('模板已加入画布，可独立修改');return true;}
