document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dropDepth++;if(!$('#drop-hint')){$('.surface').insertAdjacentHTML('beforeend','<div id="drop-hint" class="fullscreen-drop">松开文件，导入当前项目</div>');}}});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});
document.addEventListener('dragleave',e=>{dropDepth=Math.max(0,dropDepth-1);if(!dropDepth)$('#drop-hint')?.remove();});
document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();dropDepth=0;$('#drop-hint')?.remove();importFiles([...e.dataTransfer.files],e.target.closest('[data-node]')?.dataset.node).catch(e=>toast(e.message));});
document.addEventListener('input',e=>{if(e.target.id==='asset-search'){searchAssets=e.target.value;assetPage=1;assetPageRequest++;assetPageLoading=true;assetPageError='';clearTimeout(assetSearchTimer);const cursor=e.target.selectionStart;draw();const field=$('#asset-search');field.focus();field.setSelectionRange(cursor,cursor);assetSearchTimer=setTimeout(()=>loadAssetPage(),220);}});
document.addEventListener('click',e=>{const edge=e.target.closest('[data-edge]');if(edge){modal('连接关系','<p>移除这条连接不会删除节点或素材。</p>',`<button class="primary" data-action="remove-edge" data-id="${edge.dataset.edge}">移除连接</button>`);}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const message=$('#agent-prompt').value.trim(),mode=$('#agent-mode').value;if(!message||agentBusy)return;if(mode==='model')beginDirectorPlan(message).catch(e=>toast(e.message));else requestPlan(message,'local');}});
let pendingPlan=null,pendingPrompt='',pendingDirector=null;
const chatAllowance=new DirectorChatAllowance();
async function beginDirectorPlan(message){
 if(agentBusy)return;agentBusy=true;
 try{await save();health=await api('/api/health');if(!health.agentConfigured)throw Error(health.director?.error||'请先在设置中配置语言模型');pendingPrompt=message;
  if(['deepseek','miaoapi'].includes(health.director?.provider)){
    const preview=await api(`/api/projects/${project.id}/agent-preview`,{method:'POST',body:JSON.stringify({message})});
    const d=preview.director;
    // User sends each message explicitly. No cumulative chat allowance or recurring approval.
    // Keep the provider's finite per-request validation and bounded output unchanged.
    pendingDirector=null;agentBusy=false;
    return await requestPlan(message,'model',{thinking:'off',requestId:crypto.randomUUID(),projectRevision:preview.projectRevision,previewHash:preview.previewHash,authorization:{provider:d.provider,origin:d.origin,model:d.model,profileRevision:d.profileRevision,sendText:true,sendMedia:false,requestLimit:1,currency:'USD',budget:100}});
  }
  else{pendingDirector=null;modal('调用你的本机模型',`<p>会发送当前项目文字、节点关系与素材名称；图片、视频和音频文件不会发送。</p><p class="muted">模型：${esc(health.model)}</p>`,'<button data-action="close-modal">取消</button><button class="primary" data-action="confirm-model">规划操作</button>');}
 }finally{agentBusy=false;}
}
async function requestPlan(message,mode,options={}){if(agentBusy)return;agentBusy=true;const send=$('#chat-form button[type=submit]');if(send)send.disabled=true;const requestProjectId=project.id;const scroll=$('#chat-scroll');if(scroll){const row=document.createElement('div');row.className='message user';row.textContent=message;scroll.append(row);const progress=document.createElement('div');progress.id='assistant-progress';progress.className='message';progress.setAttribute('role','status');progress.textContent='助理正在回复…';scroll.append(progress);scroll.scrollTop=scroll.scrollHeight;}try{await save();toast(mode==='model'?'助理正在规划，返回后可先检查再应用…':'正在整理操作计划…');const p=await api(`/api/projects/${project.id}/agent-plan`,{method:'POST',body:JSON.stringify({message,mode,consent:mode==='model',...options})});if(project.id!==requestProjectId){toast('原项目的回答已生成，请回到原项目查看');return;}pendingPlan=p.actions.length?p:null;
   project=await api(`/api/projects/${project.id}/record-plan-answer`,{method:'POST',body:JSON.stringify({planId:p.id})});
   if(pendingPlan)pendingPlan.revision=project.revision;
   draw();$('#chat-scroll')?.scrollTo({top:$('#chat-scroll').scrollHeight,behavior:'smooth'});
 }catch(e){if(project.id!==requestProjectId){toast(e.message);return;}checkpoint();project.messages.push({role:'user',content:message},{role:'assistant',content:e.message,error:true});changed();toast(e.message);}finally{agentBusy=false;$('#assistant-progress')?.remove();const currentSend=$('#chat-form button[type=submit]');if(currentSend)currentSend.disabled=false;}}
function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSrt(){const out=editingSrt(project);if(!out)throw new Error('分镜中还没有对白或字幕');download(out,project.name+'.srt','text/plain;charset=utf-8');}
async function exportProject(){await save();download(JSON.stringify({format:'jingchang-project',version:1,project},null,2),project.name+'.json');toast('项目结构已导出；素材文件仍保存在本机');}
async function importProject(obj){if(!obj.project||!Array.isArray(obj.project.nodes))throw new Error('不是有效的镜场项目文件');await save();const fresh=await api('/api/projects',{method:'POST',body:JSON.stringify({name:obj.project.name+'（导入）'})});const p={...obj.project,id:fresh.id,revision:fresh.revision};const present=[];for(const a of p.assets||[]){const r=await fetch('/media/'+encodeURIComponent(a.id),{method:'HEAD'});if(r.ok)present.push(a);}p.assets=present;p.nodes.forEach(n=>{if(!present.some(a=>a.id===n.assetId))n.assetId=null;});p.shots.forEach(s=>{if(!present.some(a=>a.id===s.assetId))s.assetId=null;if(!present.some(a=>a.id===s.audioId))s.audioId=null;});if(p.settings?.edit?.music)p.settings.edit.music=p.settings.edit.music.filter(t=>present.some(a=>a.id===t.assetId&&a.type.startsWith('audio/')));project=await api('/api/projects/'+fresh.id,{method:'PUT',body:JSON.stringify(p)});undo=[];redo=[];selected=null;draw();toast('已导入为独立项目；跨电脑导入需重新关联素材');}
function stopPlayback(){playing=false;clearTimeout(playTimer);document.querySelectorAll('#player video,#player audio').forEach(el=>el.pause());}
let renderDraft=null,renderBusy=false;
async function beginRender(){if(renderBusy)return;renderBusy=true;try{stopPlayback();await save();toast('正在检查镜头、声音和成片时长…');const plan=await api(`/api/projects/${project.id}/render-plan`);renderDraft={projectId:project.id,revision:plan.revision,requestId:crypto.randomUUID()};modal('检查成片设置',renderPlanMarkup(plan),'<button data-action="close-modal">返回编辑</button><button class="primary" data-action="confirm-render">开始本机合成</button>');}finally{renderBusy=false;}}
async function confirmRender(){if(renderBusy||!renderDraft)return;renderBusy=true;try{await save();if(project.id!==renderDraft.projectId||project.revision!==renderDraft.revision)throw Error('剪辑已修改，请重新检查成片设置');activeJob=await api(`/api/projects/${project.id}/render`,{method:'POST',body:JSON.stringify(renderDraft)});renderDraft=null;showJob();pollJob();}finally{renderBusy=false;}}
function showJob(){if(!activeJob)return;const j=activeJob,done=j.status==='completed',recover=['failed','cancelled','interrupted'].includes(j.status),result=j.result;modal('本地视频导出',`<p style="line-height:1.8">${esc(j.message)}</p>${taskProgressMarkup(j,esc)}<p class="muted small">本机合成 · 导出时的项目版本 ${j.revision??result?.projectRevision??'—'}</p>${done?`<video controls src="${esc(result.url)}" style="width:100%;margin-top:18px;max-height:320px"></video><p class="muted small" style="margin-top:10px">${result.duration??''} 秒 · ${result.subtitlesBurned?'字幕已写入画面':'字幕独立保存'} · ${result.musicTracks||0} 条背景音频</p>`:''}`,done?`<a class="download-link" href="${esc(result.url)}" download="${esc(j.name||project.name)}.mp4">下载 MP4</a>${result.subtitleUrl?`<a class="download-link subtitle-download" href="${esc(result.subtitleUrl)}" download="${esc(j.name||project.name)}.srt">下载字幕</a>`:''}${result.attempt?`<button class="primary" data-action="apply-render" ${j.applied?'disabled':''}>${j.applied?'已加入素材库':'加入素材库'}</button>`:''}`:recover?`${j.canResume?'<button data-action="resume-render">按原设置重新合成</button>':''}<button class="primary" data-action="render-video">使用当前剪辑导出</button>`:'<button data-action="cancel-render">停止导出</button>');}

async function pollJob(){clearTimeout(jobTimer);if(!activeJob||['comfy','image-api'].includes(activeJob.kind))return;const id=activeJob.id;try{const next=await api('/api/jobs/'+id);if(activeJob?.id!==id)return;activeJob=next;if($('#modal').open&&$('#modal h2')?.textContent==='本地视频导出')showJob();if(['queued','running'].includes(activeJob.status))jobTimer=setTimeout(pollJob,1300);else toast(activeJob.message);}catch(e){toast(e.message);}}
async function extraActions(a,b){
  if(await studioBindingAction(a,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(await nativeLoopAction(a,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(a==='run-native-cascade'){await nativeCascadeDialog();return;}
  if(await nativePromptAction(a,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(await llmBindingAction(a,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(await imageBindingAction(a,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(await cloudBindingAction(a,b,{api,modal,esc,getProject:()=>project,getSelected:()=>selected,checkpoint,changed,save,toast}))return;
  if(await comfyBackendActions(a,b,{api,modal,esc,toast}))return;
  if(a==='configure-workflow-fields'){openFieldDesigner(currentWorkflow,{modal,esc});return;}
  if(await fieldDesignerAction(a,{api,workflowEditor,toast}))return;
  if(await bundleActions(a,b,{save,getProject:()=>project,api,modal,esc,toast}))return;
  if(await historyArchiveActions(a,b,{save,getProject:()=>project,api,modal,esc,toast}))return;
  if(a==='open-cloud-workflows'){await save();location.href='/cloud-workflows.html?project='+encodeURIComponent(project.id);return true;}if(['open-conversation','open-agent-conversation'].includes(a)){await save();location.href='/conversation.html?project='+encodeURIComponent(project.id)+(a==='open-agent-conversation'?'&mode=agent':'');return true;}if(a==='public-media'){await openPublicMedia({projectId:project.id,assets:project.assets,onImport:async a=>{checkpoint();project.assets.push(a);libraryAssets.unshift(a);changed(false);await save();if(view==='assets')await loadAssetPage();}});return true;}if(a==='shared-folders'){await sharedFolderDialog();return true;}if(a==='asset-catalog'){await assetCatalogDialog();return true;}if(a==='save-selection-workflow'){if(!selectedIds.size)throw Error('请先选择画布节点');await assetCatalogDialog('',true);return true;}if(a==='apimart-materials'){await save();await openApimartMaterials({projectId:project.id,assets:project.assets});return;}if(a==='ark-assets'){await openArkAssets({projectId:project.id,assets:project.assets});return;}if(a==='open-creation-studio'){await save();location.href='/creation-studio?projectId='+encodeURIComponent(project.id);return;}
  if(await apiStudioActions(a,b))return;
  if(await canvasAction(a,b))return;
  if(await studioActions(a,b))return;
  if(a==='help'){modal('操作指南',`<p style="line-height:2.1">拖动节点标题移动节点，拖动空白处平移，滚轮缩放。<br>点击节点右侧连接点，再点击目标节点左侧建立依赖。<br>点击连接线可移除关系；双击空白处添加文本节点。<br>${health?.capabilities?.smartCanvasCtrlDrag?'智能画布：按住 Ctrl 拖动标题到兼容卡片可连接并复位；循环卡片拖至连线中点可插入。图片拖到多图卡片可合并，均可撤销。<br>':''}<br>拖入素材文件可导入；TXT / Markdown 自动成为剧本节点。<br>分镜支持顺序调整、画面裁切和配音；剪辑页可添加背景声音、设置字幕并合成预览 / 导出 MP4。<br>Shift 点击 / 拖动框选多选，⌘ / Ctrl + G 编组，Shift + G 解组；D 复制选区。<br>${health?.capabilities?.canvasPointerPaste?'⌘ / Ctrl + C / V 复制粘贴到最近的画布指针位置；未移动指针时放在当前视图中心，连续粘贴保持位置。<br>':''}提示词库和全局素材库可跨项目复用。生成任务从左侧工作流入口开始。<br>⌘ / Ctrl + Z 撤销，⌘ / Ctrl + Shift + Z 重做，⌘ / Ctrl + S 保存。<br>历史版本会保留。移出画布不会删除素材文件。</p>`);}
  else if(a==='skills'){const [ss,ts]=await Promise.all([api('/api/skills'),api('/api/templates')]);modal('技能与工作流模板',`<p class="muted" style="margin-bottom:20px;line-height:1.8">本地模板创建可编辑节点与连接。不会自动提交生成任务。</p>${ss.map(s=>`<div class="project-card"><div><strong>${esc(s.name)}</strong><p class="muted" style="line-height:1.8">${esc(s.description)}</p></div><button class="subtle" data-skill="${s.id}">使用</button></div>`).join('')}<div class="section-label">我的模板</div>${ts.map(t=>`<div class="project-card"><div><strong>${esc(t.name)}</strong><p class="muted">${t.nodes.length} 个节点</p></div><button class="subtle" data-template="${t.id}">使用</button></div>`).join('')||'<p class="muted">将当前画布保存为模板，下次继续复用。</p>'}`,`<button class="primary" data-action="save-template">保存当前画布为模板</button>`);}
  else if(a==='save-template'){await save();await api('/api/templates',{method:'POST',body:JSON.stringify({projectId:project.id,name:project.name})});toast('模板已保存，不包含素材文件');await extraActions('skills');}
  else if(a==='history'){await save();const items=await api(`/api/projects/${project.id}/history`);modal('版本历史',`<p class="muted" style="margin-bottom:16px">恢复会创建新版本，不覆盖或删除旧版本。</p>${items.map(h=>`<div class="project-card"><div><strong>版本 ${h.revision} · ${esc(h.name)}</strong><span class="muted">${new Date(h.updatedAt).toLocaleString()} · ${h.nodes} 节点</span></div><button class="subtle" data-restore="${h.file}" ${h.revision===project.revision?'disabled':''}>恢复</button></div>`).join('')}`,historyArchiveToolbar());}
  else if(a==='add-shot'){checkpoint();const s={id:crypto.randomUUID(),title:`镜头 ${String(project.shots.length+1).padStart(2,'0')}`,description:'',dialogue:'',sound:'',size:'中景',camera:'固定',duration:5,assetId:null,audioId:null,sourceNodeId:null};project.shots.push(s);changed();shotDialog(s.id);}
  else if(a==='save-shot'){const form=$('#shot-form');if(!form.reportValidity())return;const f=new FormData(form),s=project.shots.find(s=>s.id===selectedShot),next={...s,duration:Number(f.get('duration'))};for(const key of ['title','description','dialogue','sound','size','camera'])next[key]=f.get(key);next.assetId=f.get('assetId')||null;next.audioId=f.get('audioId')||null;next.edit=readShotEdit(form,next);checkpoint();Object.assign(s,next);$('#modal').close();changed();}
  else if(a==='copy-shot'){checkpoint();const s=structuredClone(project.shots.find(s=>s.id===selectedShot));s.id=crypto.randomUUID();s.title+=' 副本';project.shots.push(s);$('#modal').close();changed();}
  else if(a==='remove-shot'){checkpoint();project.shots=project.shots.filter(s=>s.id!==selectedShot);selectedShot=null;$('#modal').close();changed();}
  else if(a==='split-script'){panel='agent';draw();await requestPlan('把已有剧本拆为分镜','local');}
  else if(a==='confirm-model'){if(pendingDirector){const form=$('#director-confirmation-form');if(!form?.reportValidity())return true;const d=pendingDirector;if(project.id!==d.projectId)throw Error('当前项目已切换，请重新检查');const consent=readDirectorAuthorization(form,d.director);chatAllowance.approve(project.id,d.director,consent.authorization.budget,consent.thinking);const chosen=chatAllowance.reserve(project.id,d.director,d.estimatedMaximumUSD);pendingDirector=null;$('#chat-budget-setup')?.remove();$('#modal').close();await requestPlan(d.message,'model',{...chosen,requestId:d.requestId,projectRevision:d.projectRevision,previewHash:d.previewHash});}else{$('#modal').close();await requestPlan(pendingPrompt,'model');}return true;}
  else if(a==='cancel-chat-budget'){pendingDirector=null;$('#chat-budget-setup')?.remove();return true;}
else if(a==='reset-chat-budget'){chatAllowance.clear();draw();toast('本轮聊天已结束');return true;}
else if(a==='review-chat-plan'){if(!pendingPlan||pendingPlan.projectId!==project.id)return true;modal('检查画布修改',`<p>${esc(pendingPlan.summary)}</p>${planActionsMarkup(pendingPlan,project,esc)}`,'<button data-action="close-modal">继续聊天</button><button class="primary" data-action="apply-plan">应用修改</button>');return true;}
else if(a==='apply-plan'){if(!pendingPlan)return;await save();const old=JSON.stringify(project);project=await api(`/api/projects/${project.id}/apply-plan`,{method:'POST',body:JSON.stringify({planId:pendingPlan.id})});undo.push(old);redo=[];pendingPlan=null;$('#modal').close();draw();toast('计划已应用，可撤销');}
  else if(a==='run'){await save();if(project.nodes.some(n=>n.params?.workflowBinding||n.params?.cloudBinding||n.params?.imageBinding||n.params?.llmBinding||n.params?.studioBinding)){await canvasRunDialog();return true;}const {steps}=await api(`/api/projects/${project.id}/preflight`);const blocked=steps.filter(s=>s.status==='blocked');modal('工作流运行检查',`<p style="line-height:1.8;margin-bottom:15px">${blocked.length?`${blocked.length} 个节点尚不具备执行条件。`:'节点输入已就绪。'}可运行本机 ComfyUI 生成工作流，或将现有素材合成为视频。为媒体节点绑定本机工作流后，可按连线顺序执行并传递上游图片和文字。</p>${steps.map(s=>`<div class="run-step">${icon(s.status==='ready'?'check':'time')}<div><strong>${esc(s.title)}</strong><p class="muted small" style="margin-top:6px">${esc(s.reason)}</p></div></div>`).join('')}`,`<button data-action="split-script">剧本拆镜</button><button data-action="workflows">生成工作流</button><button class="primary" data-action="render-video">合成已有分镜</button>`);}
  else if(a==='export'){modal('导出项目',`<div class="export-list"><button data-action="export-bundle">${icon('folder')}<div>完整项目备份<small>打包媒体、工作流、创作台与对话，可在另一台电脑恢复</small></div></button><button data-action="render-video">${icon('video')}<div>合成 MP4 视频<small>按分镜顺序合成现有画面与音频</small></div></button><button data-action="export-srt">${icon('text')}<div>字幕 SRT<small>按镜头时长导出对白字幕</small></div></button><button data-action="export-storyboard">${icon('grid')}<div>分镜表 CSV<small>镜头、时长、景别、运镜、对白与参考素材</small></div></button><button data-action="export-project">${icon('folder')}<div>项目 JSON<small>保存节点、连线、分镜与参数，不包含媒体文件</small></div></button></div>`);}
  else if(a==='export-project')await exportProject();
  else if(a==='export-srt')exportSrt();
  else if(a==='export-storyboard'){const cell=v=>'"'+String(v||'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('\uFEFF'+[['镜头','时长','景别','运镜','画面','对白','环境声','素材'],...project.shots.map(s=>[s.title,s.duration,s.size,s.camera,s.description,s.dialogue,s.sound,project.assets.find(a=>a.id===s.assetId)?.name||''])].map(row=>row.map(cell).join(',')).join('\r\n'),project.name+'-分镜.csv','text/csv;charset=utf-8');}
  else if(a==='edit-film')filmSettingsDialog(project,modal);
  else if(a==='save-film-edit'){const f=$('#film-edit-form');if(!f.reportValidity())return;const next=readFilmSettings(f,project);checkpoint();project.settings.edit=next;$('#modal').close();changed();}
  else if(a==='add-music'||a==='edit-music')musicDialog(project,a==='edit-music'?b.dataset.id:null,modal);
  else if(a==='save-music'){const f=$('#music-form');if(!f.reportValidity())return;const next=readMusic(f,project);checkpoint();project.settings.edit=next;$('#modal').close();changed();}
  else if(a==='remove-music'){checkpoint();const edit=normalizeEditSettings(project.settings);edit.music=edit.music.filter(t=>t.id!==b.dataset.id);project.settings.edit=edit;$('#modal').close();changed();}
  else if(a==='render-video')await beginRender();
  else if(a==='confirm-render')await confirmRender();
  else if(a==='resume-render'){if(renderBusy||!activeJob)return;renderBusy=true;try{activeJob=await api('/api/jobs/'+activeJob.id+'/resume',{method:'POST',body:'{}'});showJob();pollJob();}finally{renderBusy=false;}}
  else if(a==='apply-render'){if(renderBusy||!activeJob)return;if(activeJob.projectId!==project.id)throw Error('请先打开这份成片所属的项目，再加入素材库');renderBusy=true;try{await save();project=await api('/api/projects/'+project.id+'/render-apply',{method:'POST',body:JSON.stringify({jobId:activeJob.id,revision:project.revision})});undo=[];redo=[];activeJob=await api('/api/jobs/'+activeJob.id);draw();showJob();toast('成片已加入素材库和画布');}finally{renderBusy=false;}}
  else if(a==='cancel-render'){if(activeJob)await api('/api/jobs/'+activeJob.id+'/cancel',{method:'POST',body:'{}'});toast('已请求停止');}
  else if(a==='play-timeline')await beginRender();
  else if(a==='remove-edge'){checkpoint();project.edges=project.edges.filter(e=>e.id!==b.dataset.id);$('#modal').close();changed();}
}
function registerWebTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_jingchang_project',description:'Read current project nodes and shots without changing them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {id:project.id,name:project.name,nodes:project.nodes.map(({id,type,title})=>({id,type,title})),shots:project.shots.length};}},{name:'add_jingchang_text_node',description:'Add and save a text or script node in the current project.',inputSchema:{type:'object',properties:{type:{enum:['text','script']},title:{type:'string'},text:{type:'string'}},required:['type','title','text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||!['text','script'].includes(input.type)||typeof input.title!=='string'||input.title.length>120||typeof input.text!=='string'||input.text.length>200000)throw new Error('Invalid text node');addNode(input.type);const n=project.nodes.find(n=>n.id===selected);n.title=input.title;n.text=input.text;changed();await save();return {id:n.id,type:n.type,title:n.title};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

async function refreshAssetPage(){
  const request=++assetPageRequest;
  assetPageLoading=true;assetPageError='';
  const params=new URLSearchParams({scope:assetScope,projectId:assetScope==='project'?project.id:'',type:assetFilter,category:assetCategory,smartClass:assetSmartClass,search:searchAssets,limit:String(ASSET_PAGE_SIZE)});
  try{
    const catalog=await api('/api/asset-catalog');if(request!==assetPageRequest)return false;assetCatalogLibraries=catalog.libraries.filter(l=>!l.archived);const library=assetCatalogLibraries.find(l=>l.id===assetLibraryId);if(!library){assetLibraryId='';assetFolderId='';}else if(assetFolderId&&!library.folders.some(f=>f.id===assetFolderId&&!f.archived&&f.type==='media'))assetFolderId='';params.set('libraryId',assetLibraryId);params.set('folderId',assetFolderId);
    let result;
    for(let attempt=0;attempt<2;attempt++){
      params.set('offset',String((assetPage-1)*ASSET_PAGE_SIZE));
      result=await api('/api/assets/page?'+params);
      if(request!==assetPageRequest)return false;
      const pageCount=Math.max(1,Math.ceil(result.total/ASSET_PAGE_SIZE)),nextPage=Math.min(Math.max(1,assetPage),pageCount);
      if(nextPage===assetPage)break;
      assetPage=nextPage;
    }
    if(request!==assetPageRequest)return false;
    assetRows=Array.isArray(result.items)?result.items:[];assetTotal=Number(result.total)||0;assetSourceTotal=Number(result.sourceTotal)||0;assetCategories=Array.isArray(result.categories)?result.categories:[];assetSmartClasses=Array.isArray(result.smartClasses)?result.smartClasses:[];
    return true;
  }catch(error){if(request===assetPageRequest){assetPageError=error.message||'素材列表读取失败';assetRows=[];assetTotal=0;assetSourceTotal=0;assetCategories=[];assetSmartClasses=[];}return false;}
  finally{if(request===assetPageRequest)assetPageLoading=false;}
}
async function loadAssetPage(){const pending=refreshAssetPage(),request=assetPageRequest;if(view==='assets')draw();await pending;if(request===assetPageRequest&&view==='assets')draw();}
async function refreshLibrary({refreshPage=true}={}){if(libraryRefreshPromise)return libraryRefreshPromise;libraryRefreshPromise=api('/api/assets').then(async assets=>{libraryAssets=assets;libraryLoadedAt=Date.now();if(refreshPage&&view==='assets')await refreshAssetPage();return assets;}).finally(()=>{libraryRefreshPromise=null;});return libraryRefreshPromise;}
function assetsMarkup(){
  const pageCount=Math.max(1,Math.ceil(assetTotal/ASSET_PAGE_SIZE));
  assetPage=Math.min(Math.max(1,assetPage),pageCount);
  const start=(assetPage-1)*ASSET_PAGE_SIZE;
  const range=assetTotal?`${start+1}–${Math.min(start+assetRows.length,assetTotal)} / ${assetTotal}`:'0 / 0';
  const pager=assetTotal>ASSET_PAGE_SIZE?`<nav class="asset-pagination" aria-label="素材分页"><span class="muted small">显示 ${range}</span><div class="row"><button class="subtle" data-asset-page="${assetPage-1}" ${assetPage===1?'disabled':''} aria-label="上一页">上一页</button><span class="small" aria-live="polite">第 ${assetPage} / ${pageCount} 页</span><button class="subtle" data-asset-page="${assetPage+1}" ${assetPage===pageCount?'disabled':''} aria-label="下一页">下一页</button></div></nav>`:'';
  const cards=assetRows.map(a=>`<article class="asset-card"><div class="preview">${media(a)}</div><div class="asset-info"><strong title="${esc(a.name)}">${esc(a.name)}</strong><p class="small muted">${esc(a.category||'未分类')} ${esc((a.tags||[]).map(t=>'#'+t).join(' '))}</p>${a.classification?`<p class="small muted" title="${esc(a.classification.summary||'智能分类')}">智能分类：${esc(a.classification.summary||a.classification.tags?.slice(0,5).join(' · ')||'已完成')}</p>`:''}<div class="row asset-actions"><button data-edit-asset="${a.id}" class="subtle">管理</button>${a.type.startsWith('image/')||a.type.startsWith('video/')?`<button data-media-tool="${a.type.startsWith('video/')?'frames':'crop'}" data-asset-id="${a.id}" class="subtle">${a.type.startsWith('video/')?'抽帧':'裁剪'}</button>`:''}${a.type.startsWith('image/')?`${['image/png','image/jpeg','image/webp'].includes(a.type)?`<button class="subtle" data-caption-asset="${a.id}">图片提示词</button><button class="subtle" data-classify-asset="${a.id}">${a.classification?'重新分类':'智能分类'}</button><button class="subtle" data-classification-records="${a.id}">分类记录</button>`:''}<button class="subtle" data-image-enhance="${a.id}">增强 / 放大</button>${a.enhancement?`<button class="subtle" data-enhance-compare="${a.id}">前后对比</button>`:''}<button class="subtle" data-camera-angle="${a.id}">机位</button><button class="subtle" data-panorama="${a.id}">全景</button><button class="subtle" data-image-edit="${a.id}">编辑</button><button class="subtle" data-grid-tool="split" data-asset-id="${a.id}">宫格</button>`:''}${a.type==='application/x-safetensors'?`<button class="subtle" data-lora-asset="${a.id}">LoRA 文件与上传</button>`:`<button class="subtle" data-use-asset="${a.id}">${icon('plus')}放入画布</button>`}</div></div></article>`).join('');
  const results=assetPageLoading?`<div class="empty" role="status"><p>正在读取当前页素材…</p></div>`:assetPageError?`<div class="empty"><h2>素材列表暂时无法读取</h2><p>${esc(assetPageError)}</p><button class="subtle" data-asset-reload>重新加载</button></div>`:assetRows.length?`<div class="cards">${cards}</div>${pager}`:`<div class="empty">${icon('image')}<h2>暂无匹配素材</h2><p>导入文件、复用其他项目素材，或在生成工作流中创建素材。</p><button class="subtle" data-action="upload">选择本机文件</button></div>`;
  return `<div class="scroll-view"><div class="view-heading"><div><h2>${assetScope==='global'?'全局素材库':'项目资产'}</h2><p class="muted small" style="margin-top:8px">${assetTotal} / ${assetSourceTotal} 份素材符合当前筛选</p></div><div class="row"><button class="subtle" data-grid-tool="compose">图片拼接</button><button class="primary" data-action="upload">${icon('upload')}导入素材</button></div></div><div class="filters"><button data-asset-scope="project" class="${assetScope==='project'?'active':''}">当前项目</button><button data-asset-scope="global" class="${assetScope==='global'?'active':''}">全部项目</button><select id="asset-library-filter" aria-label="独立素材库"><option value="">所有素材库与未分组素材</option>${assetCatalogLibraries.map(l=>`<option value="${esc(l.id)}" ${l.id===assetLibraryId?'selected':''}>${esc(l.name)}</option>`).join('')}</select><select id="asset-folder-filter" aria-label="素材库分组" ${assetLibraryId?'':'disabled'}><option value="">全部媒体分组</option>${(assetCatalogLibraries.find(l=>l.id===assetLibraryId)?.folders||[]).filter(f=>!f.archived&&f.type==='media').map(f=>`<option value="${esc(f.id)}" ${f.id===assetFolderId?'selected':''}>${esc(f.name)}</option>`).join('')}</select><select id="asset-category" aria-label="素材分类"><option value="">全部分类标签</option>${assetCategories.map(c=>`<option value="${esc(c)}" ${c===assetCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="asset-smart-class" aria-label="智能分类"><option value="">全部智能分类</option>${assetSmartClasses.map(c=>`<option value="${esc(c.id)}" ${c.id===assetSmartClass?'selected':''}>${esc(c.label)} / ${esc(c.tag)} (${c.count})</option>`).join('')}</select></div><div class="filters">${[['all','全部'],['image','图片'],['video','视频'],['audio','音频'],['text','文本'],['lora','LoRA'],['3d','三维']].map(([v,t])=>`<button data-filter="${v}" class="${assetFilter===v?'active':''}">${t}</button>`).join('')}<button class="subtle" data-action="asset-catalog">库与分组管理</button><button class="subtle" data-action="shared-folders">共享文件夹</button><button data-action="ark-assets">火山素材库</button>${health?.capabilities?.apimartMaterials?'<button data-action="apimart-materials">APIMart素材</button>':''}<button data-action="public-media">公网素材链接</button><input id="asset-search" type="search" placeholder="搜索名称、标签或图片分类" value="${esc(searchAssets)}" aria-label="搜索素材"></div>${results}</div>`;
}
