let assetClassificationPlatforms=[];
const assetClassificationPending=new Map();
async function showAssetClassificationRecords(assetId,taskId=''){if($('#modal').open)$('#modal').close();await openAssetClassificationTasks({assetId,assetName:([...assetRows,...libraryAssets,...project.assets].find(asset=>asset.id===assetId)?.name||''),taskId,onRead:rows=>{const id=assetClassificationPending.get(assetId);if(rows.some(row=>row.id===id&&!['queued','sending'].includes(row.status)))assetClassificationPending.delete(assetId);},onCompleted:async()=>{await refreshLibrary();if(view==='assets')await loadAssetPage();}});}
async function openAssetClassification(id){
  if(assetClassificationPending.has(id)){await showAssetClassificationRecords(id,assetClassificationPending.get(id));return;}
  const asset=assetRows.find(item=>item.id===id)||libraryAssets.find(item=>item.id===id)||project.assets.find(item=>item.id===id);
  if(!asset||!['image/png','image/jpeg','image/webp'].includes(asset.type))throw new Error('智能分类只支持 PNG、JPEG、WebP 图片');
  if(asset.size>10*1024*1024)throw new Error('图片超过 10 MB，暂不支持智能分类');
  const state=await api('/api/platforms');
  assetClassificationPlatforms=state.platforms.filter(p=>p.protocol==='openai-compatible'&&p.models.some(m=>m.category==='chat'&&m.referenceSupport));
  if(!assetClassificationPlatforms.length){modal('设置图片分类模型','<p class="muted" style="line-height:1.9">请先在 API 设置中添加 OpenAI 兼容平台，并将一个对话模型分类为“对话模型”、开启“支持图片输入”。平台配置不保存 API Key。</p>','<button data-action="close-modal">关闭</button><button class="primary" data-action="api-settings">打开 API 设置</button>');return;}
  const first=assetClassificationPlatforms[0],firstModels=first.models.filter(m=>m.category==='chat'&&m.referenceSupport);
  modal('图片智能分类',`<div class="media-tool-preview"><img src="/media/${encodeURIComponent(id)}" alt="${esc(asset.name)}"></div><p class="muted small">${esc(asset.name)} · ${Math.ceil(asset.size/1024)} KB · 只处理这一张图片</p><form id="asset-classification-form" data-asset-id="${esc(id)}"><label>平台<select name="platformId">${assetClassificationPlatforms.map(p=>`<option value="${esc(p.id)}" ${p.id===first.id?'selected':''}>${esc(platformDisplayName(p))}</option>`).join('')}</select></label><label>图片理解模型<select name="model">${firstModels.map(m=>`<option value="${esc(m.id)}">${esc(modelDisplayName(m))}</option>`).join('')}</select></label><p id="asset-classification-origin" class="muted small" style="overflow-wrap:anywhere"></p><label>API Key（仅本次请求，不保存）<input type="password" name="apiKey" autocomplete="off" placeholder="本机免认证模型可留空"></label><label>补充分类要求（可选）<textarea name="prompt" rows="2" maxlength="4000" placeholder="例如：优先标注适合文旅宣传片的元素"></textarea></label><div id="asset-classification-budget"><div class="row"><label>本次预算<input name="budget" type="number" min="0.01" step="0.01" placeholder="填写你允许的预算"></label><label>币种<select name="currency"><option value="CNY">人民币</option><option value="USD">美元</option></select></label></div><p class="muted small">预算是本次授权记录，实际扣费由平台决定，工作台不能强制限制上游扣费。</p></div><label class="check-label"><input name="consent" type="checkbox" required>我同意将这张图片和补充说明发送给上方服务，最多提交 1 次。</label><p class="notice">图片会离开本机发送到所选模型。分类前请确认图片适合交给该服务处理。结果会保存在本机素材信息中。</p></form>`,`<button data-action="close-modal">取消</button><button data-classification-records="${esc(id)}">分类记录</button><button data-action="api-settings">API 设置</button><button class="primary" data-action="submit-asset-classification">分类这一张图片</button>`);
  const form=$('#asset-classification-form');
  const update=()=>{const platform=assetClassificationPlatforms.find(p=>p.id===form.elements.platformId.value),models=(platform?.models||[]).filter(m=>m.category==='chat'&&m.referenceSupport),before=form.elements.model.value;form.elements.model.innerHTML=models.map(m=>`<option value="${esc(m.id)}" ${m.id===before?'selected':''}>${esc(modelDisplayName(m))}</option>`).join('');const url=new URL(platform.baseUrl),local=url.protocol==='http:'&&['127.0.0.1','localhost','[::1]'].includes(url.hostname);$('#asset-classification-origin').textContent=`图片发送目标：${url.origin} · 仅 1 张图片 / 1 次请求`;$('#asset-classification-budget').hidden=local;form.elements.apiKey.required=!local;form.elements.budget.required=!local;mountMiaoCredentialChoice(form.elements.apiKey,platform);};
  form.elements.platformId.addEventListener('change',()=>{form.elements.apiKey.value='';form.elements.consent.checked=false;form.elements.budget.value='';update();});form.elements.model.addEventListener('change',()=>{form.elements.consent.checked=false;});update();
}
async function submitAssetClassification(button){
  const form=$('#asset-classification-form');if(!form||!form.reportValidity())return;
  if(form.dataset.submitted==='true'){await showAssetClassificationRecords(form.dataset.assetId,form.dataset.requestId);return;}
  const f=new FormData(form),platform=assetClassificationPlatforms.find(p=>p.id===f.get('platformId')),model=platform?.models.find(m=>m.id===f.get('model')&&m.category==='chat'&&m.referenceSupport);
  if(!platform||!model)throw new Error('请选择已保存的平台和支持图片输入的对话模型');
  const parsedUrl=new URL(platform.baseUrl),origin=parsedUrl.origin,local=['127.0.0.1','localhost','[::1]'].includes(parsedUrl.hostname)&&parsedUrl.protocol==='http:';
  const assetId=form.dataset.assetId,requestId=form.dataset.requestId||crypto.randomUUID();form.dataset.requestId=requestId;
  const payload={requestId,projectId:project.id,platformId:platform.id,model:model.id,...readMiaoCredentialChoice(form.elements.apiKey),prompt:String(f.get('prompt')||''),consent:f.get('consent')==='on',authorization:{origin,model:model.id,sendImage:true,requestLimit:1,budget:local?0:Number(f.get('budget')),currency:String(f.get('currency')||'CNY'),consent:f.get('consent')==='on'}};
  f.delete('apiKey');form.dataset.submitted='true';assetClassificationPending.set(assetId,requestId);form.elements.apiKey.value='';button.disabled=true;
  try{
    const response=await fetch(`/api/assets/${encodeURIComponent(assetId)}/classify`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json();
    if(!response.ok){const error=new Error(result.error||'分类请求未完成');error.classificationTask=result.classificationTask;throw error;}
    if(result.classificationTask?.status&&result.classificationTask.status!=='completed'){if(form.isConnected&&$('#modal').open||document.querySelector('#asset-classification-tasks-dialog')?.dataset.assetId===assetId)await showAssetClassificationRecords(assetId,result.classificationTask.id||requestId);return;}
    if(assetClassificationPending.get(assetId)===requestId)assetClassificationPending.delete(assetId);
    await refreshLibrary();
    const c=result.classification||result.classificationTask?.result||{},labels={environment:'环境',scene:'场景',space:'空间',subject:'主体',model:'模特',people:'人物',style:'风格',lighting:'光影',color:'色彩',composition:'构图',mood:'氛围',use_case:'用途',objects:'物体',materials:'材质',quality:'质量',tags:'标签'};
    const details=[...(c.summary?[`<p>${esc(c.summary)}</p>`]:[]),...Object.entries(c.categories||{}).map(([key,tags])=>`<p class="small"><strong>${esc(labels[key]||key)}：</strong> ${esc(tags.join('、'))}</p>`),...(c.tags?.length?[`<p class="small muted">关键词：${esc(c.tags.join(' · '))}</p>`]:[])].join('');
    // Another read-only dialog may already be showing this request while its POST completes.
    if(document.querySelector('#asset-classification-tasks-dialog')?.dataset.assetId===assetId)await openAssetClassificationTasks({assetId,taskId:requestId});
    if(form.isConnected&&$('#modal').open&&!document.querySelector('#asset-classification-tasks-dialog'))modal('图片分类完成',`${details||'<p>模型没有返回可用标签。</p>'}<p class="muted small">使用 ${esc(modelDisplayName(model))} · 结果和原请求收据已保存在本机，可用智能分类筛选。</p>`,`<button data-classification-records="${esc(assetId)}" data-classification-task="${esc(result.classificationTask?.id||requestId)}">分类记录</button><button class="primary" data-action="close-modal">完成</button>`);
    if(view==='assets')await loadAssetPage();
  }catch(error){
    // A lost response is not authorization to resend. Recover the exact receipt by GET only.
    let task=error.classificationTask;
    if(!task)try{const response=await fetch('/api/asset-classification-tasks/'+encodeURIComponent(requestId));if(response.ok)task=await response.json();}catch{}
    if(task){if(form.isConnected&&$('#modal').open||document.querySelector('#asset-classification-tasks-dialog')?.dataset.assetId===assetId)await showAssetClassificationRecords(assetId,task.id||requestId);}
    else if(form.isConnected&&$('#modal').open&&!document.querySelector('#asset-classification-tasks-dialog'))modal('图片分类结果待核对',`<p class="notice">${esc(error.message)}</p><p>尚未读取到本次收据，上游是否接收仍待核对。请先读取原记录与核对平台账单，不要直接重新发送图片。</p><p class="small muted">请求编号：${esc(requestId)}</p>`,`<button data-classification-records="${esc(assetId)}" data-classification-task="${esc(requestId)}">读取原分类记录</button><button class="primary" data-action="close-modal">关闭</button>`);
  }finally{payload.apiKey='';form.elements.apiKey.value='';}
}
