let taskCenterEpoch=0;
async function taskCenter(pasteOffset=0){
 const epoch=++taskCenterEpoch,projectId=project.id;
 const tasks=await api('/api/jobs?projectId='+projectId);
 const paging=health?.capabilities?.clipboardPastePaging;
 const result=health?.capabilities?.smartGroupStoredMedia?await api('/api/projects/'+projectId+'/clipboard-pastes'+(paging?'?limit=50&offset='+pasteOffset:'')):[];
 if(project.id!==projectId||epoch!==taskCenterEpoch)return;
 taskItems=tasks;const pastes=Array.isArray(result)?result:result.items;
 const navigation=paging&&result.total>50?`<nav class="actions" aria-label="粘贴记录分页">${result.offset>0?`<button data-action="tasks" data-paste-offset="${Math.max(0,result.offset-result.limit)}">上一页</button>`:''}<span class="small muted" role="status">${result.items.length?result.offset+1:0}–${result.offset+result.items.length} / ${result.total} 条</span>${result.nextOffset!==null?`<button data-action="tasks" data-paste-offset="${result.nextOffset}">下一页</button>`:''}<button data-action="tasks">回到最新</button></nav>`:'';
 modal('任务中心',`${pastes.length||navigation?'<h3>本机粘贴记录</h3>'+pastes.map(r=>`<div class="project-card"><div><strong>${esc(r.name)}</strong><p class="small muted">${r.status==='completed'?'已保存':'尚未完成'} · ${r.nodes} 个节点</p></div><button data-clipboard-paste="${esc(r.id)}">读取${r.canResume?'与继续':''}</button></div>`).join('')+navigation+'<h3>生成与合成记录</h3>':''}<p class="muted small">当前项目的生成与合成记录。关闭窗口不会停止后台任务。</p>${taskItems.map(j=>`<div class="project-card"><div><strong>${esc(j.name||(j.kind==='comfy'?'生成素材':'视频合成'))}</strong><p class="muted small">${esc(j.message)}</p><span class="small">${esc(({preparing:'准备中','awaiting-confirmation':'待确认上传',expired:'已过期',queued:'排队中',running:'进行中',completed:'已完成',failed:'失败',cancelled:'已停止',interrupted:'已中断'})[j.status]||j.status)} · ${new Date(j.createdAt).toLocaleString()}</span></div><button class="subtle" data-task="${j.id}">查看</button></div>`).join('')||'<div class="empty"><p>还没有任务。到生成工作流或剪辑页面开始。</p></div>'}`,`<button class="subtle" data-action="tasks">刷新记录</button><button class="primary" data-action="workflows">生成工作流</button>`);
}
