  const candidates=imageContext.candidates||[],candidateIds=candidates.map(a=>typeof a==='string'?a:a.id);const boundIds=(n.params?.imageBinding?.referenceSources||[]).map(r=>r.assetId||project.nodes.find(x=>x.id===r.sourceNodeId)?.assetId).filter(id=>project.assets.some(a=>a.id===id));const desiredIds=[...new Set([...boundIds,...candidateIds])];const defaultIds=desiredIds.length<=IMAGE_REFERENCE_LIMIT?desiredIds:[];
  modal('图片生成与编辑',`<form id="direct-image-form" data-node="${n.id}"><label>本节点提示词<textarea name="prompt" rows="4" maxlength="32000" placeholder="描述画面，或说明怎样修改参考图…">${esc(n.text)}</textarea></label><label class="check-label"><input name="includeUpstream" type="checkbox" checked>带入相连的上游文本、剧本、角色和场景描述（${imageContext.upstreamNodeIds.length} 个上游节点）</label><div class="row"><input type="hidden" name="platformId" value="${esc(chosen?.id||'')}"><label>图片模型<select name="model" required>${imageModelOptions(chosen,n.params?.model)}</select></label></div>${available.length?'':'<p class="notice">请先在 API 设置中配置图片模型服务。</p>'}<div class="row"><label>输出尺寸<input name="size" list="image-sizes" value="${esc(n.params?.imageSize||'auto')}" required><datalist id="image-sizes"><option value="auto">由模型决定</option><option value="1024x1024">1:1</option><option value="1536x1024">3:2</option><option value="1024x1536">2:3</option><option value="1536x864">16:9</option><option value="864x1536">9:16</option><option value="2048x1152">16:9 · 2K</option><option value="3840x2160">16:9 · 4K</option></datalist></label><label>质量<select name="quality">${[['auto','自动'],['low','低'],['medium','中'],['high','高']].map(([v,t])=>`<option value="${v}" ${n.params?.quality===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="muted small">填写精确尺寸或 auto；尺寸和质量是否支持取决于你选的模型。不会失败后自动切换模型。</p><details ${candidateIds.length?'open':''}><summary>参考图（最多 20 张）</summary><label>从本机添加参考图<input id="direct-reference-files" type="file" accept="image/png,image/jpeg,image/webp" multiple></label>${candidateIds.length>IMAGE_REFERENCE_LIMIT?`<p class="notice">上游有 ${candidateIds.length} 张参考图，请手动选择最多 20 张。</p>`:''}<div class="reference-picker">${project.assets.filter(a=>['image/png','image/jpeg','image/webp'].includes(a.type)).map(a=>`<label class="reference-choice"><input type="checkbox" name="referenceIds" value="${a.id}" ${defaultIds.includes(a.id)?'checked':''}><img src="/media/${a.id}" alt=""><span>${esc(a.name)}${candidateIds.includes(a.id)?' · 上游':''}</span></label>`).join('')||'<p class="muted small">先将图片导入项目，再从这里选择。也可将上游图片节点连到当前节点。</p>'}</div></details><details><summary>遮罩重绘（可选）</summary><label>本机图片编辑器生成的 PNG 遮罩<select name="maskAssetId"><option value="">不使用遮罩</option>${project.assets.filter(a=>a.type==='image/png'&&a.operation==='image-edit'&&a.editOutput==='mask').map(a=>`<option value="${a.id}" data-source-asset="${a.sourceAssetId||''}">${esc(a.name)}${Number.isInteger(a.width)&&Number.isInteger(a.height)?` · ${a.width}×${a.height}`:''}</option>`).join('')}</select></label><p id="image-mask-support-hint" class="muted small">使用遮罩时需且仅需选择一张对应的底图；底图和遮罩像素尺寸必须一致。</p><p class="muted small">请在 API 设置核实所选模型支持 OpenAI 图片编辑 JSON 遮罩格式。遮罩和底图都会发送到你选择的平台。</p></details><div class="section-label">本次调用</div><p id="image-service-origin" class="muted small" style="overflow-wrap:anywhere"></p><label>API Key（仅本次请求，不保存）<input type="password" name="apiKey" autocomplete="off" placeholder="本机免认证接口可留空"></label><div id="cloud-image-authorization"><div class="row"><label>本次预算<input name="budget" type="number" min="0.01" step="0.01" placeholder="填写你允许的预算"></label><label>币种<select name="currency"><option value="CNY">人民币</option><option value="USD">美元</option></select></label></div><label class="check-label"><input name="consent" type="checkbox">同意向所选平台发送本次提示词、勾选的参考图和遮罩，最多请求 1 次。</label><p class="muted small">预算是本次授权记录；实际扣费由平台决定，工作台不能强制限制上游扣费。提交不确定时不会自动重试。</p></div></form>`,`<button data-action="api-settings">API 设置</button><button data-action="generate-workflow">本机工作流</button><button class="primary" data-action="submit-direct-image" ${available.length?'':'disabled'}>生成 1 张图片</button>`);
  updateImageService();
  await mountMiaoCredentialChoice($('#direct-image-form').elements.apiKey,chosen,{purpose:'image'});
