async function canvasRunDialog(nodeId=null){canvasRunMode='ordinary';canvasPreviewHash='';canvasRunTarget=nodeId;const {steps}=await api('/api/projects/'+project.id+'/canvas-run-plan'+(nodeId?'?nodeId='+encodeURIComponent(nodeId):''));canvasSteps=steps;canvasRunRequest=crypto.randomUUID();const needsComfy=steps.some(s=>s.kind==='comfy'||!s.kind),backendHtml=needsComfy?await backendPicker(api,esc,{parallel:steps.some(s=>s.nativeLoop?.mode==='parallel'&&s.kind==='comfy')}):'';modal('按连线运行画布',`<p>将${steps.some(s=>s.nativeLoop?.mode==='parallel')?'按循环模式执行':'顺序执行'} ${steps.length} 个执行步骤，合计 ${steps.reduce((n,s)=>n+s.count,0)} 次生成。上游完成后按已保存映射传递文字与素材；单素材字段使用明确选定的序号，失败即停止后续节点。${steps.some(s=>s.nativeBranch)?'智能分支按实际计数选择；此检查包含同一循环的完整分支候选，未选分支不提交。':''}结果完成后可加入画布。</p>${backendHtml}${steps.map((s,i)=>`<div class="run-step canvas-plan-step">${i+1}. ${esc(s.title)}${s.loopId?` · ${esc(s.loopTitle)} 第${s.roundIndex+1}/${s.roundCount}轮${s.nativeLoop?` · 计数 ${s.nativeLoop.index}/${s.nativeLoop.total} · ${s.nativeLoop.mode==='parallel'?'并行':'串行'}`:''}`:''} · ${s.kind==='runninghub'?(s.minimaxH3?'RunningHub H3 当前片段 · '+s.minimaxH3.segments.find(c=>c.id===s.minimaxH3.selectedSegmentId).duration+'秒':'RunningHub'):s.kind==='image-api'?'图片接口':s.kind==='canvas-llm'?'语言模型':s.kind==='studio'?'创作接口':s.minimaxH3?'H3 当前片段 · '+s.minimaxH3.segments.find(c=>c.id===s.minimaxH3.selectedSegmentId).duration+'秒':s.ltxDirector?'LTX 导演 · '+s.ltxDirector.durationFrames+'帧':'ComfyUI'} · ${s.count} 次${s.loopFields?.length?`<p class="small muted">${s.loopFields.map(f=>esc(f.kind==='minimax'?'H3 '+minimaxParameterNames[f.name]:f.name)+' = '+esc(String(f.value).slice(0,160))).join(' · ')}</p>`:''}${s.kind==='comfy'||!s.kind?nativeReferenceMarkup(s,esc):''}${randomScopeMarkup(s.randomDescriptors,esc)}${nativeBranchMarkup(s.nativeBranch,esc,id=>project.nodes.find(n=>n.id===id)?.title||id)}${nativeCascadeRequestMarkup(s,esc)}</div>`).join('')}${cloudAuthorizationMarkup(steps,esc)}${imageAuthorizationMarkup(steps,esc)}${llmAuthorizationMarkup(steps,esc)}${studioAuthorizationMarkup(steps,esc)}<p class="muted small">预算为授权记录，不能强制限制上游扣费。${needsComfy?'ComfyUI节点使用本次选定的后端。自定义工作流可能包含云服务节点，请先核对其费用与发送范围。停止等待不会撤销 ComfyUI 已提交的计算。':''}</p><label class="check-label"><input id="canvas-run-consent" type="checkbox">已检查以上节点，确认发送到各自服务执行</label>`,`<button data-action="close-modal">取消</button><button class="primary" data-action="start-canvas-run">开始执行</button>`);await Promise.all([installImageCredentialChoices(steps),installLlmCredentialChoices(steps)]);}
