async function startCanvasRun(button){if(!$('#canvas-run-consent').checked)throw new Error('请先确认执行范围');button.disabled=true;try{activeJob=await api('/api/projects/'+project.id+'/canvas-run',{method:'POST',body:JSON.stringify({revision:project.revision,requestId:canvasRunRequest,...(canvasRunMode==='native-cascade'?{executionMode:canvasRunMode,previewHash:canvasPreviewHash}:{}),...(canvasRunTarget?{nodeId:canvasRunTarget}:{}),cloudCredentials:readCloudCredentials(canvasSteps),imageCredentials:readImageCredentials(canvasSteps),llmCredentials:readLlmCredentials(canvasSteps),studioCredentials:readStudioCredentials(canvasSteps),backendId:document.querySelector('[name=backendId]')?.value,...(document.querySelector('[name=parallelBackendId]:checked')?{parallelBackendIds:[...document.querySelectorAll('[name=parallelBackendId]:checked')].map(input=>input.value)}:{}),consent:true})});showCanvasRun();pollCanvasRun();}finally{clearCloudInputs();clearImageInputs();clearLlmInputs();clearStudioInputs();if(button.isConnected)button.disabled=false;}}
function showCanvasRun(){const j=activeJob,ongoing=['running','queued'].includes(j.status),partial=!ongoing&&j.status!=='completed'&&(j.assets.some(a=>!(j.appliedAssetIds||[]).includes(a.id))||(j.textResults||[]).some(r=>!(j.appliedTextIds||[]).includes(r.id)));modal('画布执行任务',`<p>${esc(j.message)}</p>${legacyNativeInputAuditMarkup(j.legacyNativeInputAudit,esc)}${j.backend&&j.steps.some(s=>s.kind==='comfy'||!s.kind)?`<p class="muted small">ComfyUI 后端：${esc(j.backend.name)} · ${esc(j.backend.url)}</p>`:''}${j.steps.map(s=>`<div class="run-step canvas-execution-step">${esc(s.title)}${s.loopId?` · 第${s.roundIndex+1}/${s.roundCount}轮${s.nativeLoop?` · 计数 ${s.nativeLoop.index}/${s.nativeLoop.total} · ${s.nativeLoop.mode==='parallel'?'并行':'串行'}`:''}`:''} · ${esc(!ongoing&&j.status!=='completed'&&['submitting','running'].includes(s.status)?'待继续':({pending:'待执行',submitting:'提交中',running:'执行中',completed:'完成'})[s.status]||s.status)}${s.kind==='canvas-llm'?`<p class="small muted" style="overflow-wrap:anywhere">服务：${esc(platformDisplayName(s.llm.platform))} · ${esc(s.llm.platform.baseUrl)} · ${esc(s.llm.model)}</p>`:''}${s.kind==='studio'&&s.childMessage?`<p class="small muted">${esc(s.childMessage)}</p>`:''}${s.kind==='studio'&&s.upstreamId?`<p class="small muted" style="overflow-wrap:anywhere">原任务编号：${esc(s.upstreamId)}</p>`:''}${randomReceiptMarkup({...s,id:s.jobId},esc)}${nativeBranchMarkup(s.nativeBranch,esc,id=>project.nodes.find(n=>n.id===id)?.title||id)}${nativeCascadeRequestMarkup(s,esc)}</div>${(s.kind==='canvas-llm'||s.outputType==='string')&&s.outputText?`<details class="canvas-text-result" open><summary>${s.status==='completed'?'完整文字结果':'已收到的文字（尚未完成，不传给下游）'}</summary><pre>${esc(s.outputText)}</pre></details>`:''}`).join('')}<div class="job-results">${j.assets.map(a=>`<div>${media(a)}${a.enhancement?`<button data-enhance-compare="${a.id}">增强前后对比</button>`:''}</div>`).join('')}</div>`,(j.legacyNativeInputAudit?.state==='requires_confirmation'?'<button data-action="review-native-inputs">核对旧任务素材</button>':'')+(ongoing?'<button data-action="cancel-canvas-run">停止后续执行</button>':j.status==='completed'?`<button class="primary" data-action="apply-generation" ${j.applied?'disabled':''}>${j.applied?'已加入项目':'加入当前项目'}</button>`:j.canResume===false?'<button data-action="tasks">查看任务记录</button>':'<button data-action="resume-canvas-run">继续原画布任务</button>')+(partial?'<button data-action="apply-partial-generation">仅取回已完成步骤</button>':''));}
async function pollCanvasRun(){clearTimeout(canvasRunTimer);const id=activeJob?.id;if(activeJob?.kind!=='canvas-run')return;try{const j=await api('/api/jobs/'+id);if(activeJob?.id!==id)return;activeJob=j;if($('#modal').open&&$('#modal h2')?.textContent==='画布执行任务')showCanvasRun();if(['queued','running'].includes(j.status))canvasRunTimer=setTimeout(pollCanvasRun,1000);else await refreshLibrary();}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='review-native-inputs'){await reviewNativeInputs(b);return;}if(b.dataset.action==='confirm-native-input-review'){await confirmNativeInputs(b);return;}if(b.dataset.action==='cancel-canvas-run'){b.disabled=true;await api('/api/jobs/'+activeJob.id+'/cancel',{method:'POST',body:'{}'});}if(b.dataset.action==='resume-canvas-run'){if(activeJob.steps.some(s=>(s.kind==='runninghub'||s.kind==='studio'||['image-api','canvas-llm'].includes(s.kind)&&!s.jobId)&&s.status!=='completed')){const displaySteps=reviewedNativeInputDisplaySteps(activeJob.steps,activeJob.legacyNativeInputAudit);modal('继续原画布任务',legacyNativeInputAuditMarkup(activeJob.legacyNativeInputAudit,esc)+cloudAuthorizationMarkup(displaySteps,esc,true)+imageAuthorizationMarkup(displaySteps,esc,true)+llmAuthorizationMarkup(displaySteps,esc,true)+studioAuthorizationMarkup(displaySteps,esc,true),'<button data-action="close-modal">取消</button><button class="primary" data-action="confirm-resume-cloud-canvas">继续原任务</button>');await Promise.all([installImageCredentialChoices(activeJob.steps,true),installLlmCredentialChoices(activeJob.steps,true)]);return;}await resumeCanvasWithKeys(b);}if(b.dataset.action==='confirm-resume-cloud-canvas')await resumeCanvasWithKeys(b);}catch(e){b.disabled=false;toast(e.message);}});

function workflowSourceIssuesMarkup(issues){
 if(!issues.length)return'';
 return `<section class="notice" role="alert" data-workflow-source-issues><strong>以下素材映射暂时不能编辑</strong><ul>${issues.map(issue=>`<li>#${esc(issue.nodeId)} ${esc(issue.name)} · ${esc(issue.label)}：${esc(issue.reason)}</li>`).join('')}</ul><p>原素材来源和序号已保留。请点击“设置字段表单”，恢复这些字段的显示和媒体用途后再绑定或运行。</p></section>`;
}
function restoreWorkflowBinding(node){
 const b=node?.params?.workflowBinding;if(!b||b.workflowId!==currentWorkflow.id)return;const form=$('#generation-form');if(!form)return;
 generationFields.forEach((field,i)=>{
  const override=b.overrides?.find(f=>f.nodeId===field.nodeId&&f.name===field.name),image=b.imageSources?.find(f=>f.nodeId===field.nodeId&&f.name===field.name),input=form.elements['field-'+i];
  if(override&&input){if(input.type==='checkbox')input.checked=override.value;else input.value=String(override.value);const slider=document.querySelector(`[data-field-slider="${i}"]`);if(slider)slider.value=String(override.value);}
  if(image&&field.imageInput){
   const select=form.elements['binding-'+i],indexInput=form.elements['sourceIndex-'+i];
   if(select&&indexInput){
    const value=image.sourceNodeId?'node:'+image.sourceNodeId:image.assetId;
    if(![...select.options].some(option=>option.value===value)){const option=document.createElement('option');option.value=value;option.textContent='已保存来源（当前不可用）：'+(project.nodes.find(n=>n.id===image.sourceNodeId)?.title||image.sourceNodeId||image.assetId);select.append(option);}
    select.value=value;syncWorkflowSourceControl(form,i);indexInput.value=sourceIndexToInput(image.sourceIndex);if(input)input.disabled=true;
   }
  }
  if(b.promptField?.nodeId===field.nodeId&&b.promptField?.name===field.name&&form.elements.promptField)form.elements.promptField.value=String(i);
 });
 restoreRandomFields(form,generationFields,b.randomFields??(b.minimaxH3||b.ltxDirector?[]:undefined));if(form.elements.count)form.elements.count.value=b.count||1;if(form.elements.incrementSeeds)form.elements.incrementSeeds.value=String(b.incrementSeeds===true);
}

let pendingNativeInputReview=null;
async function reviewNativeInputs(button){
 const id=activeJob?.id,projectId=activeJob?.projectId;if(!id||project.id!==projectId)throw Error('请先打开原任务所属的项目。');button.disabled=true;
 try{const preview=await api('/api/jobs/'+id+'/native-input-review/preview',{method:'POST',body:'{}'});
  if(activeJob?.id!==id||project.id!==projectId)return;
  if(preview.jobId!==id||preview.projectId!==projectId||preview.generationSubmitted!==false)throw Error('任务核对回执不一致，请刷新记录。');
  pendingNativeInputReview=preview.canConfirm===true?{id,projectId,fingerprint:preview.audit.fingerprint}:null;
  modal('核对旧任务素材',nativeInputReviewPreviewMarkup(preview,esc),'<button data-action="close-modal">返回</button>'+(preview.canConfirm===true?'<button class="primary" data-action="confirm-native-input-review">确认这些素材序号</button>':''));
 }finally{if(button.isConnected)button.disabled=false;}
}
async function confirmNativeInputs(button){
 const pending=pendingNativeInputReview;
 if(!pending||activeJob?.id!==pending.id||project.id!==pending.projectId)throw Error('原任务已变化，请重新查看素材差异。');
 if(!$('#native-input-review-consent')?.checked)throw Error('请先核对序号并勾选确认。');button.disabled=true;
 try{const result=await api('/api/jobs/'+pending.id+'/native-input-review/confirm',{method:'POST',body:JSON.stringify({fingerprint:pending.fingerprint,consent:true})});
  if(result.generationSubmitted!==false||result.job?.id!==pending.id||result.job.projectId!==pending.projectId)throw Error('素材确认回执不一致，请刷新任务记录。');
  if(activeJob?.id!==pending.id||project.id!==pending.projectId||pendingNativeInputReview!==pending)return;
  activeJob=result.job;pendingNativeInputReview=null;showCanvasRun();
 }finally{if(button.isConnected)button.disabled=false;}
}
async function resumeCanvasWithKeys(button){button.disabled=true;try{const cloudCredentials=readCloudCredentials(activeJob.steps,true);activeJob=await api('/api/jobs/'+activeJob.id+'/resume',{method:'POST',body:JSON.stringify({cloudCredentials,imageCredentials:readImageCredentials(activeJob.steps,true),llmCredentials:readLlmCredentials(activeJob.steps,true),studioCredentials:readStudioCredentials(activeJob.steps,true),consent:true})});showCanvasRun();pollCanvasRun();}finally{clearCloudInputs();clearImageInputs();clearLlmInputs();clearStudioInputs();if(button.isConnected)button.disabled=false;}}

document.querySelector('#modal').addEventListener('close',()=>{if($('#modal').open)return;clearCloudInputs();clearImageInputs();clearLlmInputs();clearStudioInputs();});

async function customMediaConnection(sourceId,targetId){
 const source=project.nodes.find(n=>n.id===sourceId),target=project.nodes.find(n=>n.id===targetId);
 if(!source||!target)return null;
 const workflow=target.params?.workflowBinding,cloud=target.params?.cloudBinding;
 if(!workflow&&!cloud)return null;
 const choice=nativeReferenceChoices({...project,edges:[...project.edges,{id:'native-flow-prospective',source:sourceId,target:targetId}]},targetId).find(item=>item.value==='node:'+sourceId);
 if(workflow){
  const mappings=workflow.imageSources||[];
  if(mappings.some(item=>item.sourceNodeId===source.id))return {alreadyMapped:true};
  if(choice?.grouped||workflowSourceNeedsIndex(source))return {manual:true,grouped:true,service:'ComfyUI'};
  if(!['image','video','audio'].includes(source.type))return null;
  const template=await api('/api/workflows/'+encodeURIComponent(workflow.workflowId));
  const occupied=new Set(mappings.map(item=>JSON.stringify([item.nodeId,item.name])));
  const fields=(template.inspection?.nodes||[]).flatMap(node=>effectiveInputs(template,node)
   .filter(input=>input.type==='string'&&comfyMediaField(node.class_type,input.name,input.config)?.kinds.includes(source.type))
   .map(input=>({nodeId:node.id,name:input.name})))
   .filter(field=>!occupied.has(JSON.stringify([field.nodeId,field.name])));
  if(fields.length===1)return {bindingKey:'workflowBinding',service:'ComfyUI',field:{...fields[0],sourceNodeId:source.id}};
  return {manual:true,service:'ComfyUI',count:fields.length};
 }
 if(cloud){
  const mappings=cloud.inputs||[];
  if(mappings.some(item=>item.sourceNodeId===source.id))return {alreadyMapped:true};
  if(choice?.grouped||workflowSourceNeedsIndex(source))return {manual:true,grouped:true,service:'RunningHub'};
  if(!['image','video','audio'].includes(source.type))return null;
  const recipe=await api('/api/cloud-workflows/'+encodeURIComponent(cloud.recipeId));
  const occupied=new Set(mappings.map(item=>JSON.stringify([item.nodeId,item.fieldName])));
  const fields=(recipe.fields||[]).filter(field=>field.type===source.type&&field.source!=='lora'&&!occupied.has(JSON.stringify([field.nodeId,field.fieldName])));
  if(fields.length===1)return {bindingKey:'cloudBinding',service:'RunningHub',field:{nodeId:fields[0].nodeId,fieldName:fields[0].fieldName,sourceNodeId:source.id}};
  return {manual:true,service:'RunningHub',count:fields.length};
 }
 return null;
}
async function connectCanvasNodes(source,target){
 connectFrom=null;
 let error=connectionError(project,source,target);
 if(error){draw();throw new Error(error);}
 let custom;try{custom=await customMediaConnection(source,target);}catch(error){draw();throw error;}
 error=connectionError(project,source,target);
 if(error){draw();throw new Error(error);}
 const mapping=connectionMediaMapping(project,source,target);
 checkpoint();project.edges.push({id:crypto.randomUUID(),source,target});
 if(mapping){const binding=project.nodes.find(n=>n.id===mapping.targetId).params[mapping.bindingKey];binding.referenceSources??=[];if(!binding.referenceSources.some(r=>r.sourceNodeId===mapping.reference.sourceNodeId))binding.referenceSources.push(mapping.reference);}
 if(custom?.field){const binding=project.nodes.find(n=>n.id===target).params[custom.bindingKey];if(custom.bindingKey==='workflowBinding'){binding.imageSources??=[];binding.imageSources.push(custom.field);}else{binding.inputs??=[];binding.inputs.push(custom.field);}}
 changed();
 if(mapping)toast(`已连接，并自动映射${labels[project.nodes.find(n=>n.id===source)?.type]||'媒体'}参考`);
 else if(custom?.field)toast(`已连接，并自动映射到${custom.service}的唯一兼容媒体字段`);
 else if(custom?.grouped)toast(`已连接整组来源；请编辑 ${custom.service} 绑定并明确选择素材，未自动选取首份`);
 else if(custom?.manual)toast(custom.count?`已连接：有 ${custom.count} 个${custom.service}媒体字段可选，请在节点输入设置中手动选择`:`已连接，但此${custom.service}配置没有空闲的${labels[project.nodes.find(n=>n.id===source)?.type]||'兼容'}媒体字段`);
 else if(custom?.alreadyMapped)toast('此上游素材已映射到当前工作流字段');
 else if(['image','video','audio'].includes(project.nodes.find(n=>n.id===source)?.type)&&['workflowBinding','cloudBinding'].some(key=>project.nodes.find(n=>n.id===target)?.params?.[key]))toast('连线已建立；请在节点输入设置中选择对应的上游媒体字段');
}
installCanvasInteractions({
  enabled:()=>!!project&&view==='canvas',viewport:()=>project.viewport,labels,
  connectionError:(s,t)=>connectionError(project,s,t),connect:connectCanvasNodes,notify:toast,
  selectContext:id=>{if(!selectedIds.has(id))selectNodes([id]);else selected=id;panel='inspector';draw();},
  edit:id=>{selectNodes([id]);panel='inspector';draw();},
  removeEdge:id=>{checkpoint();project=removeConnection(project,id);changed();},
  duplicate:duplicateSelection,remove:removeSelection,action:canvasAction,add:addNode,fit,
  selectAll:()=>{selectNodes(project.nodes.map(n=>n.id));draw();}
});

async function handleImageGrid(b){return imageGridAction(b,{modal,esc,media,api,notify:toast,refresh:refreshLibrary,assets:()=>libraryAssets,apply:applyImageAssets});}
function applyImageAssets(outputs){
  checkpoint();const ids=[],v=project.viewport,c=$('#canvas')?.getBoundingClientRect(),x=((c?.width||900)/2-v.x)/v.zoom-144,y=(160-v.y)/v.zoom;
  for(const [i,a] of outputs.entries()){if(!project.assets.some(old=>old.id===a.id))project.assets.push(structuredClone(a));const id=crypto.randomUUID();ids.push(id);project.nodes.push({id,type:'image',title:a.name,text:'',x:x+(i%4)*330,y:y+Math.floor(i/4)*300,assetId:a.id,params:{ratio:project.settings.ratio}});}
  selectNodes(ids);view='canvas';panel=null;changed();fit();}
