async function handleCameraAngle(b){return cameraAngleAction(b,{
 modal,esc,api,save,refresh:refreshLibrary,project:()=>project,assets:()=>libraryAssets,notify:toast,
 commit:async({nodeId,sourceNodeId,asset,params,text})=>{
  checkpoint();if(asset&&!project.assets.some(a=>a.id===asset.id))project.assets.push(asset);
  let n=project.nodes.find(n=>n.id===nodeId);
  if(n){n.params=params;n.text=text;}else{const source=project.nodes.find(n=>n.id===sourceNodeId),x=source?source.x+360:180,y=source?source.y:180;n={id:crypto.randomUUID(),type:'image',title:'机位图片',text,params,x,y,assetId:null};project.nodes.push(n);if(source)project.edges.push({id:crypto.randomUUID(),source:source.id,target:n.id});}
  selected=n.id;selectedIds=new Set([n.id]);view='canvas';panel='inspector';changed();await save();fit();toast('机位已保存，运行工作流可生成图片');
 },
 remove:async id=>{const n=project.nodes.find(n=>n.id===id);if(!n)return;checkpoint();delete n.params.cameraAngle;changed();await save();toast('机位指令已移除，节点和生成配置保留');},
 run:canvasRunDialog
});}
function effectiveGenerationPrompt(nodeId){const seen=new Set(),texts=[];function visit(id){if(seen.has(id))return;seen.add(id);for(const e of project.edges.filter(e=>e.target===id))visit(e.source);const n=project.nodes.find(n=>n.id===id);if(n)texts.push(cameraNodeText(n));}visit(nodeId);return texts.filter(Boolean).join('\n\n');}

async function handleMinimaxH3(b){
 const n=project.nodes.find(n=>n.id===selected),targetNodeId=['generate-node','edit-node-workflow','bind-cloud-node'].includes(b.dataset.action)&&minimaxTimelineOf(n)?selected:null;
 return minimaxH3Action(b,{targetNodeId,modal,esc,api,save,refresh:refreshLibrary,project:()=>project,assets:()=>libraryAssets,notify:toast,
  commit:async({nodeId,params,assets})=>{checkpoint();for(const a of assets)if(!project.assets.some(x=>x.id===a.id))project.assets.push(a);let n=project.nodes.find(n=>n.id===nodeId);if(n)n.params=params;else{n={id:crypto.randomUUID(),type:'video',title:'MiniMax H3',text:'',x:180,y:Math.max(0,...project.nodes.map(n=>n.y))+330,assetId:null,params};project.nodes.push(n);}selected=n.id;selectedIds=new Set([n.id]);menu=false;view='canvas';panel='inspector';changed();await save();fit();toast('H3 时间轴已保存到本机');return n;},run:canvasRunDialog,
  export:async(nodeId,selectedOnly)=>{await save();activeJob=await api('/api/projects/'+project.id+'/minimax-export',{method:'POST',body:JSON.stringify({revision:project.revision,requestId:crypto.randomUUID(),nodeId,selectedOnly})});showJob();pollJob();}});
}

