async function handleImageEnhance(b){
 const n=project.nodes.find(n=>n.id===selected);if(['generate-node','edit-node-workflow','bind-studio-node'].includes(b.dataset.action)&&enhancementOf(n))b.dataset.enhanceNode=selected;
 return imageEnhanceAction(b,{modal,esc,api,save,refresh:refreshLibrary,assets:()=>libraryAssets,project:()=>project,notify:toast,
  commit:async({nodeId,sourceNodeId,asset,params,text,kind,next})=>{
   checkpoint();if(asset&&!project.assets.some(a=>a.id===asset.id))project.assets.push(asset);let node=project.nodes.find(n=>n.id===nodeId);const source=project.nodes.find(n=>n.id===sourceNodeId);
   if(node){node.params=params;node.text=text;}else{node={id:nodeId,type:'image',title:kind==='upscale'?'SeedVR2 放大':'细节增强',text,params,x:source?source.x+350:180,y:source?source.y:Math.max(0,...project.nodes.map(n=>n.y))+320,assetId:null};project.nodes.push(node);}
   if(source&&!project.edges.some(e=>e.source===source.id&&e.target===node.id))project.edges.push({id:crypto.randomUUID(),source:source.id,target:node.id});
   if(next){project.nodes.push({id:next.id,type:'image',title:'SeedVR2 放大',text:'',params:next.params,x:node.x+350,y:node.y,assetId:null});project.edges.push({id:crypto.randomUUID(),source:node.id,target:next.id});}
   selected=node.id;selectedIds=new Set([node.id]);view='canvas';panel='inspector';menu=false;changed();await save();fit();toast('增强流程已保存，可检查并运行');
  },run:canvasRunDialog});
}

async function sharedFolderDialog(jobId=''){await save();await openSharedFolders({projectId:project.id,jobId,onClassify:async sourceImportId=>openClassificationBatches({projectId:project.id,sourceImportId,onRead:async()=>{await refreshLibrary();if(view==='assets')draw();}}),getRevision:async()=>{await save();return project.revision;},onImport:async()=>{await refreshLibrary();},onApply:async p=>{project=p;undo=[];redo=[];dirty=false;await refreshLibrary();draw();}});}

async function assetCatalogDialog(jobId='',saveSelection=false,backupJobId=''){await save();await openAssetCatalog({saveSelection,backupJobId,getSelection:()=>[...selectedIds].filter(id=>project.nodes.some(n=>n.id===id)),getPlacement:()=>{const c=$('#canvas')?.getBoundingClientRect(),v=project.viewport;return {x:((c?.width||900)/2-v.x)/v.zoom-144,y:(180-v.y)/v.zoom};},onInsert:async result=>{
 if(project.id!==result.project.id){toast('工作流已插入原项目，可返回查看');return;}
 if(savePromise)try{await savePromise;}catch{}
 const nodeIds=result.nodeIds.filter(id=>result.project.nodes.some(n=>n.id===id)),newIds=nodeIds.filter(id=>!project.nodes.some(n=>n.id===id));
 if(newIds.length)checkpoint();
 if(dirty){
  for(const [key,ids]of [['nodes',result.nodeIds],['edges',result.edgeIds],['groups',result.groupIds],['assets',result.assetIds||[]]]){project[key]??=[];for(const item of result.project[key]||[])if(ids.includes(item.id)&&!project[key].some(old=>old.id===item.id))project[key].push(structuredClone(item));}
  for(const run of result.project.runs.filter(r=>r.kind==='canvas-fragment'&&r.nodeIds?.some(id=>nodeIds.includes(id))))if(!project.runs.some(r=>r.id===run.id))project.runs.push(structuredClone(run));
  project.revision=Math.max(project.revision,result.project.revision);changed(false);
 }else{project=result.project;dirty=false;}
 selectedIds=new Set(nodeIds.filter(id=>project.nodes.some(n=>n.id===id)));selected=[...selectedIds][0]||null;view='canvas';menu=false;await refreshLibrary();draw();if(selectedIds.size)fit();toast(selectedIds.size?'工作流已插入，可继续编辑或运行':'原插入记录已完成，节点可能已被移出画布');
 },projectId:project.id,jobId,getRevision:async()=>{await save();return project.revision;},onChange:async()=>{await refreshLibrary();if(view==='assets')draw();},onApply:async p=>{project=p;undo=[];redo=[];dirty=false;await refreshLibrary();draw();},onUseAsset:async asset=>{if(!project.assets.some(a=>a.id===asset.id)){checkpoint();project.assets.push(structuredClone(asset));}useAsset(asset);await save();},onUseWorkflow:async workflowId=>{await workflowEditor(workflowId);}});}
